"use strict";(self.webpackChunkedicai_documentation=self.webpackChunkedicai_documentation||[]).push([[849],{6164(i){i.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"main":[{"type":"category","label":"Administrator Workflows","collapsed":false,"items":[{"type":"link","href":"/docs/training/overview","label":"Administrator Training \u2014 Overview","docId":"training/overview","unlisted":false},{"type":"link","href":"/docs/training/getting_started","label":"Getting Started & Orientation","docId":"training/getting_started","unlisted":false},{"type":"link","href":"/docs/training/settings_institution","label":"Institution Settings & Users","docId":"training/settings_institution","unlisted":false},{"type":"link","href":"/docs/training/teaching_calendar","label":"Academic Years & Semesters","docId":"training/teaching_calendar","unlisted":false},{"type":"link","href":"/docs/training/teaching_structure","label":"Academic Structure & Campuses","docId":"training/teaching_structure","unlisted":false},{"type":"link","href":"/docs/training/student_life","label":"Student Life \u2014 Students, Guardians & Discipline","docId":"training/student_life","unlisted":false},{"type":"link","href":"/docs/training/admissions","label":"Admissions \u2014 Cycles & Applicant Pipeline","docId":"training/admissions","unlisted":false},{"type":"link","href":"/docs/training/finance","label":"Finance \u2014 Fee Structures & Payments","docId":"training/finance","unlisted":false},{"type":"link","href":"/docs/training/examinations","label":"Examinations \u2014 Hall Tickets & Grading","docId":"training/examinations","unlisted":false},{"type":"link","href":"/docs/training/campus_ops","label":"Campus Operations \u2014 Facilities & Transport","docId":"training/campus_ops","unlisted":false},{"type":"link","href":"/docs/training/careers","label":"Careers \u2014 Placements, Alumni & Scholarships","docId":"training/careers","unlisted":false},{"type":"link","href":"/docs/training/insights","label":"Insights \u2014 Analytics & Reporting","docId":"training/insights","unlisted":false},{"type":"link","href":"/docs/training/comms_ai","label":"Communications & AI \u2014 Notices & Notifications","docId":"training/comms_ai","unlisted":false},{"type":"link","href":"/docs/training/website_apps","label":"Website & Apps \u2014 Review & Safety","docId":"training/website_apps","unlisted":false},{"type":"link","href":"/docs/training/quick_reference","label":"Administrator Quick Reference","docId":"training/quick_reference","unlisted":false}],"collapsible":true}]},"docs":{"training/admissions":{"id":"training/admissions","title":"Admissions \u2014 Cycles & Applicant Pipeline","description":"Navigation: Admissions \u2192 Admission (Admission Cycles, Applicants, Admission Enrollments, Stages, Entrance Tests, Offer Letters, Enrollments, Configuration) plus a CRM section for lead management (checklist steps 13\u201315 live here).","sidebar":"main"},"training/campus_ops":{"id":"training/campus_ops","title":"Campus Operations \u2014 Facilities & Transport","description":"Campus operations depend on the campus hierarchy established in Act I: Campus \u2192 Building \u2192 Floor \u2192 Room. Facilities attach to a campus; transport routes and passes are also scoped to the institution and campus. The examples below use Main Campus, Engineering Block, Ground Floor, Engineering Exam Hall, and the student Aarav Sharma.","sidebar":"main"},"training/careers":{"id":"training/careers","title":"Careers \u2014 Placements, Alumni & Scholarships","description":"The Careers workspace contains placement drives, recruiting companies, student applications, skill assessment, thesis management and events. Scholarship administration is under Finance \u2192 Scholarships in this build. Alumni support extends the existing student record rather than creating a separate Alumni model.","sidebar":"main"},"training/comms_ai":{"id":"training/comms_ai","title":"Communications & AI \u2014 Notices & Notifications","description":"This chapter covers how Edicai communicates with students, guardians, faculty and staff, and how Edicai AI fits into the workflow. It contains announcements and operational messaging, not academic decisions. Do not use an announcement, notification or AI response as the only record of an academic outcome; keep the authoritative record in the relevant module.","sidebar":"main"},"training/examinations":{"id":"training/examinations","title":"Examinations \u2014 Hall Tickets & Grading","description":"Navigation: Examinations for exam schedules and tickets; Grading for grade entries, verification and semester results. Before this module, make sure the course, academic offering, enrolled student and grade scale are ready.","sidebar":"main"},"training/finance":{"id":"training/finance","title":"Finance \u2014 Fee Structures & Payments","description":"Navigation: Finance \u2192 Fees \u2014 Fee Operations (Outstanding Invoices, All Invoices, Overdue Fees, Batch GL Migration), My Fees, and Configuration (Fee Structures, Accounting Configuration).","sidebar":"main"},"training/getting_started":{"id":"training/getting_started","title":"Getting Started & Orientation","description":"1.1 Logging in","sidebar":"main"},"training/insights":{"id":"training/insights","title":"Insights \u2014 Analytics & Reporting","description":"Use Insights \u2192 Analytics for Edicai\'s operational reports. The menu is grouped into Student Analytics (Enrollment Trends, Attendance Analytics), Academic Analytics (Grade Distribution, Semester Results), Financial Analytics (Fee Collection, Payment Methods) and Admission Analytics (Admission Funnel, Category Distribution). Finance Reports provides related finance dashboard and analysis views.","sidebar":"main"},"training/overview":{"id":"training/overview","title":"Administrator Training \u2014 Overview","description":"Audience: System administrators","sidebar":"main"},"training/quick_reference":{"id":"training/quick_reference","title":"Administrator Quick Reference","description":"Use this page for the short version. For details, screenshots and warnings, follow the linked chapter.","sidebar":"main"},"training/settings_institution":{"id":"training/settings_institution","title":"Institution Settings & Users","description":"This chapter documents institution setup and user roles directly; using the demo onboarding checklist is optional.","sidebar":"main"},"training/student_life":{"id":"training/student_life","title":"Student Life \u2014 Students, Guardians & Discipline","description":"Navigation: Student Life workspace (Students \u25b8 All Students / Documents / Leave Requests / Academic History / Guardians / Guardian-Student Links, plus Discipline, Mentoring, Attendance, Progression, Secure Transcripts, Grievances).","sidebar":"main"},"training/teaching_calendar":{"id":"training/teaching_calendar","title":"Academic Years & Semesters","description":"This chapter provides the operational setup sequence; it does not require completing the demo onboarding checklist.","sidebar":"main"},"training/teaching_structure":{"id":"training/teaching_structure","title":"Academic Structure & Campuses","description":"Navigation: Institution \u2192 Academic Structure (Faculties, Departments, Programs, Specialisations).","sidebar":"main"},"training/website_apps":{"id":"training/website_apps","title":"Website & Apps \u2014 Review & Safety","description":"Website and Apps are administrator-controlled areas, not routine operations. The public website is the institution\'s external face; Apps controls the modules installed in the database. Review before you change either area. This chapter documents the safe review workflow observed in UAT. It deliberately does not publish a page, edit products or install a module.","sidebar":"main"}}}}')}}]);